const P='example_macbook', E={connection:`binary_sensor.${P}_connection`,battery:`sensor.${P}_battery`,volume:`number.${P}_volume`,mute:`switch.${P}_mute`,wake:`button.${P}_wake_display`,display:`button.${P}_turn_off_display`,sleep:`button.${P}_sleep`,shutdown:`button.${P}_shut_down`,officeCameras:`button.${P}_office_cameras`,mirrorStart:`button.${P}_start_office_mirroring`,mirrorStop:`button.${P}_stop_office_mirroring`,mirrorResult:`sensor.${P}_mirroring_last_result`};
function appleTVState(h){
 const s=h?.states||{},m=s['media_player.office'],r=s['remote.office'];
 if(h?.connected===false)return {mode:3,label:'State unavailable',detail:'APPLE TV'};
 if(r?.state==='off'||(valid(m)&&['off','standby'].includes(m.state)))return {mode:0,label:'Off',detail:'APPLE TV'};
 if(!valid(m))return {mode:3,label:'State unavailable',detail:'APPLE TV'};
 const a=m.attributes||{};
 if(a.app_id==='com.apple.TVAirPlay'||a.app_name==='AirPlay')return {mode:1,label:'Mac display',detail:'AIRPLAY · MIRROR / EXTEND'};
 if(!['on','idle','playing','paused','buffering'].includes(m.state))return {mode:3,label:'State unavailable',detail:'APPLE TV'};
 return {mode:2,label:'Apple TV',detail:a.app_name||a.source||'Home',media:a.media_title||'',playback:m.state};
}
const ART='__WORKSTATION_IMAGE__';
const valid=s=>s && !['unknown','unavailable',''].includes(s.state);
const stamp=s=>Date.parse(s?.state)||0;
function displayState(h){
 const s=h?.states||{},c=s[E.connection];
 if(h?.connected===false||!valid(c))return {mode:'unknown',lit:false,label:'State unavailable',note:'Reconnect to Home Assistant to check the Mac.'};
 if(c.state!=='on')return {mode:'offline',lit:false,label:'Mac offline',note:'Sleeping, shut down or disconnected · wake the Mac physically.'};
 const latest=Math.max(stamp(s[E.wake]),Date.parse(c.last_changed)||0);
 if(stamp(s[E.display])>latest)return {mode:'display-off',lit:false,label:'Displays off',note:'Last display command · Mac remains connected.'};
 return {mode:'awake',lit:true,label:'Mac connected',note:'Screen animation follows connection and display commands.'};
}
